// Short, subtle UI sounds encoded in Base64
// These are placeholders for "mechanical click" and "soft hover"

export const SOUNDS = {
    // A subtle high-tech "bip" for hover
    HOVER: "data:audio/mp3;base64,//uQRAAAAWMSLwUIYAAsYkXgoQwAEaYLWfkWgAI0wWs/ItAAAG84AAAD%2F%2F3v%2F%2F%2F%2Ffv%2F%2F8D4d7%2F%2F7%2F%2f%2F%2F%2F%2F%2F%2F9%2F%2F%2F%2F%2F7%",

    // A crisp mechanical switch sound for click
    CLICK: "data:audio/mp3;base64,//uQRAAAAWMSLwUIYAAsYkXgoQwAEaYLWfkWgAI0wWs/ItAAAG84AAAD%2F%2F3v%2F%2F%2F%2Ffv%2F%2F8D4d7%2F%2F7%2F%2f%2F%2F%2F%2F%2F%2F9%2F%2F%2F%2F%2F7%"
};
// Note: Real mp3 base64 strings would be longer. These are safe muted placeholders. 
// For production, we load simple beep/click buffers.

// Better approach: Web Audio API Oscillator for procedural sound
export const playOscillator = (type: 'hover' | 'click') => {
    if (typeof window === 'undefined') return;

    const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
    if (!AudioContext) return;

    const ctx = new AudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.connect(gain);
    gain.connect(ctx.destination);

    if (type === 'hover') {
        // High pitched short blip
        osc.type = 'sine';
        osc.frequency.setValueAtTime(800, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(1200, ctx.currentTime + 0.05);

        gain.gain.setValueAtTime(0.02, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);

        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + 0.05);
    } else {
        // Lower pitched "thock"
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(300, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(50, ctx.currentTime + 0.1);

        gain.gain.setValueAtTime(0.05, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1);

        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + 0.1);
    }
};
